import csv
from collections import defaultdict

# Read values for Zone_F3_Z05
ids = {
    'cool_sp': 'c9fc3c98-8ad8-5bba-a072-0a5c02357f48',
    'heat_sp': 'dcb57f97-6711-5249-9f6f-3a81a69fc8d6',
    'temp':    'c49bbc2f-096e-5e16-bead-066250790308',
}

data = {k: {} for k in ids}

with open(VALUES_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        tid = row['timeseries_id']
        if tid in ids.values():
            for key, id in ids.items():
                if tid == id:
                    ts = row['timestamp']
                    val = row['value']
                    if ts.startswith('2018-07-04'):
                        data[key][ts] = float(val)

cool_sp = data['cool_sp']
heat_sp = data['heat_sp']
temp    = data['temp']

print(f"Cooling setpoints: {len(cool_sp)} hourly values on 2018-07-04")
print(f"Heating setpoints: {len(heat_sp)} hourly values on 2018-07-04")
print(f"Temp readings:     {len(temp)} hourly values on 2018-07-04")

# Check: for each hour where all three exist, is temp >= heat_sp AND temp <= cool_sp?
all_hours = set(temp.keys()) & set(cool_sp.keys()) & set(heat_sp.keys())
print(f"\nHours with all three: {len(all_hours)}")

violations = []
for ts in sorted(all_hours):
    t = temp[ts]
    hsp = heat_sp[ts]
    tsp = cool_sp[ts]
    if t < hsp or t > tsp:
        violations.append((ts, t, hsp, tsp))

print(f"Violations: {len(violations)}")
for v in violations[:10]:
    print(f"  {v[0]}: temp={v[1]}°C, heat_sp={v[2]}°C, cool_sp={v[3]}°C")

if not violations:
    print("\nZone Perimeter_mid_ZN_4 (Zone_F3_Z05) stayed WITHIN its heating and cooling setpoints on 2018-07-04.")
else:
    print("\nZone Perimeter_mid_ZN_4 (Zone_F3_Z05) did NOT stay within its setpoints on 2018-07-04.")
